mapper.delete:
delete from BOK_BAL_TABLE_DATA A
where 
    EXISTS(
    SELECT 1  
    FROM BOK_BATCH_TASK_TODO B
    WHERE  
      B.BOOKSET_ID =  A.BOOKSET_ID

      AND B.SEQ_NO = #{seqNo}
      AND B.BOOKSET_DATE = #{BOOKSET_DATE}
      AND B.TASK_ID = #{taskId}

      AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
    )
    AND A.BAL_DATE >= #{BOOKSET_DATE}

delete from BOK_VAL_TABLE_DATA A
where 
    EXISTS(
    SELECT 1  
    FROM BOK_BATCH_TASK_TODO B
    WHERE  
      B.BOOKSET_ID =  A.BOOKSET_ID

      AND B.SEQ_NO = #{seqNo}
      AND B.BOOKSET_DATE = #{BOOKSET_DATE}
      AND B.TASK_ID = #{taskId}
      AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
    )
AND A.VAL_DATE >= #{BOOKSET_DATE}

delete from BOK_VALBAL_TABLE_LOG A
where 
    EXISTS(
    SELECT 1  
    FROM BOK_BATCH_TASK_TODO B
    INNER JOIN BOK_BOOKSET C ON C.BOOKSET_ID = B.BOOKSET_ID AND ACCT_SUBJECT_TYPE = #{acctSubjectType}
    WHERE  
      C.ACCT_SUBJECT_ID =  A.FINPROD_ID

      AND B.SEQ_NO = #{seqNo}
      AND B.BOOKSET_DATE = #{BOOKSET_DATE}
      AND B.TASK_ID = #{taskId}
      AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
    )
 AND A.VAL_DATE >= #{BOOKSET_DATE}
 and A.VAL_BAL_FLAG = #{FILE_TYPE}

delete from BOK_VALBAL_TABLE_STATUS A
where 
    EXISTS(
    SELECT 1  
    FROM BOK_BATCH_TASK_TODO B
    INNER JOIN BOK_BOOKSET C ON C.BOOKSET_ID = B.BOOKSET_ID AND ACCT_SUBJECT_TYPE = #{acctSubjectType}
    WHERE  
      C.ACCT_SUBJECT_ID =  A.FINPROD_ID

      AND B.SEQ_NO = #{seqNo}
      AND B.BOOKSET_DATE = #{BOOKSET_DATE}
      AND B.TASK_ID = #{taskId}
      AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
    )
AND A.VAL_DATE >= #{BOOKSET_DATE}
and A.VAL_BAL_FLAG = #{FILE_TYPE}

delete from BOK_VALBAL_TABLE_STATUS A
where
EXISTS(
SELECT 1
FROM BOK_BATCH_TASK_TODO B
INNER JOIN BOK_BOOKSET C ON C.BOOKSET_ID = B.BOOKSET_ID AND ACCT_SUBJECT_TYPE = #{acctSubjectType}
WHERE
C.ACCT_SUBJECT_ID =  A.FINPROD_ID

AND B.SEQ_NO = #{seqNo}
AND B.BOOKSET_DATE = #{BOOKSET_DATE}
AND B.TASK_ID = #{taskId}
AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
)
AND A.VAL_DATE >= #{BOOKSET_DATE}
and A.VAL_BAL_FLAG = #{FILE_TYPE}
AND (A.confirm_status != 1 or A.confirm_status is null)
